import {form,field,number as num,select as sel,text,area,result,outputText,e,n,error} from '../ui.mjs';
import {secureIndex} from '../core.mjs';
import {durationSeconds,formatDuration} from '../advanced-core.mjs';
import {cricketBalls,plateLoad} from './calc-core.mjs';
import {need,table,exportCSV,timerDisplay} from './shared.mjs';
export function setupSport(tool,mount,out){const id=tool.id,show=o=>result(out,o);if(id==='tournament-bracket')return bracket(mount,out);if(id==='chess-clock')return chess(mount,out);if(id==='interval-timer')return intervals(mount,out);if(id==='reaction-test')return reaction(mount,out);if(id==='aim-trainer')return aim(mount,out);if(id==='memory-game')return memory(mount,out);
 const forms={
 'running-pace':()=>form(mount,[num('distance','Distance',5,.01,1000),sel('unit','Distance unit',[['km','Kilometers'],['mi','Miles']],'km'),text('time','Elapsed time (HH:MM:SS)','00:30:00'),num('split','Split distance (same unit)',1,.01,100)],v=>{const seconds=durationSeconds(v.time);need(seconds>0,'Enter a time greater than zero.');const km=+v.distance*(v.unit==='mi'?1.609344:1),pace=seconds/+v.distance,count=Math.ceil(+v.distance/+v.split);need(count<=200,'Choose a split length producing 200 or fewer rows.');const rows=Array.from({length:count},(_,i)=>{const d=Math.min(+v.distance,(i+1)*+v.split);return[d+' '+v.unit,formatDuration(d*pace)];});show({label:'Average pace',value:formatDuration(pace).replace(/^00:/,'')+' / '+v.unit,details:[['Average speed',n(km/(seconds/3600))+' km/h']],html:table(['Distance','Cumulative time'],rows),copy:rows.map(r=>r.join(' — ')).join('\n')});},{label:'Calculate pace & splits'}),
 'cricket-run-rate':()=>form(mount,[num('score','Runs scored',100,0,10000,1),text('overs','Overs completed (over.ball)','12.3'),num('target','Target score to win',180,1,10000,1),num('maximum','Total overs in innings',20,1,1000,1),num('balls','Legal balls per over',6,4,8,1)],v=>{const done=cricketBalls(v.overs,+v.balls),total=+v.maximum*+v.balls;need(done<=total,'Completed balls cannot exceed the innings limit.');const left=total-done,runs=Math.max(0,+v.target-+v.score);show({label:runs===0?'Target reached':'Required run rate',value:runs===0?'Won':left?n(runs/left*+v.balls)+' / over':'No balls remaining',details:[['Current run rate',done?n(+v.score/done*+v.balls)+' / over':'No legal balls yet'],['Runs needed',runs],['Legal balls remaining',left],['Overs notation',Math.floor(left/+v.balls)+'.'+left%+v.balls]],copy:runs===0?'Target reached':`${runs} runs from ${left} balls`});},{label:'Calculate scoring rates'}),
 'one-rep-max':()=>form(mount,[num('weight','Weight lifted (kg)',60,.1,1000),num('reps','Repetitions completed',5,1,10,1)],v=>{const a=+v.reps===1?+v.weight:+v.weight*(1+ +v.reps/30),b=+v.reps===1?+v.weight:+v.weight*36/(37-+v.reps);show({label:'Epley estimate',value:n(a)+' kg',details:[['Brzycki estimate',n(b)+' kg'],['Set entered',v.weight+' kg × '+v.reps],['Epley equation','weight × (1 + reps / 30)']],copy:`Epley: ${a.toFixed(2)} kg; Brzycki: ${b.toFixed(2)} kg`,note:'Estimates from a 1–10 repetition set, not a recommendation to attempt a maximum lift. At one repetition, the entered weight is already a completed single.'});},{label:'Estimate one-rep max'}),
 'plate-calculator':()=>form(mount,[num('target','Target total (kg)',80,0,1000,.25),num('bar','Bar weight (kg)',20,0,100,.25),area('plates','Plate weight, pairs available — one per line','20, 2\n15, 1\n10, 2\n5, 2\n2.5, 2\n1.25, 2')],v=>{const pairs=v.plates.trim().split(/\n/).map(line=>{const a=line.split(/[ ,;]+/).map(Number);need(a.length===2&&a.every(Number.isFinite)&&Number.isInteger(a[0]*4),'Use weight, pair count with weights in 0.25 kg increments.');return{weight:a[0],count:a[1]};});need(pairs.length<=12,'Use at most 12 plate denominations.');const r=plateLoad(+v.target,+v.bar,pairs);show({label:'Attainable total',value:n(r.actual)+' kg',details:[['Each side',r.perSide.length?r.perSide.map(x=>x+' kg').join(' + '):'Empty bar'],['Difference from target',n(r.shortfall)+' kg'],['Plate count per side',r.perSide.length]],copy:r.actual+' kg total; each side: '+r.perSide.join(' + ')});},{label:'Find plates'}),
 'training-volume':()=>form(mount,[area('sets','Exercise | sets | reps per set | weight (kg)','Squat | 3 | 8 | 50\nRow | 3 | 10 | 30')],v=>{const rows=v.sets.trim().split(/\n/).filter(Boolean).map(line=>{const a=line.split('|').map(s=>s.trim());need(a.length===4&&a[0]&&a.slice(1).every(x=>x!==''&&Number.isFinite(+x)&&+x>=0),'Use exercise | sets | reps | weight on each line.');return{name:a[0],sets:+a[1],reps:+a[2],weight:+a[3],volume:+a[1]*+a[2]*+a[3]};});need(rows.length<=100,'Use up to 100 exercise rows.');show({label:'External training volume',value:n(rows.reduce((s,r)=>s+r.volume,0))+' kg·reps',html:table(['Exercise','Repetitions','Volume (kg·reps)'],rows.map(r=>[r.name,r.sets*r.reps,n(r.volume)])),copy:JSON.stringify(rows,null,2),note:'This measures weight × repetitions, not the quality or safety of a workout.'});exportCSV(out,rows,'nepocore-training-volume.csv');},{label:'Calculate session volume'}),
 'cycling-gears':()=>form(mount,[num('front','Chainring teeth',50,10,100,1),num('rear','Sprocket teeth',17,5,80,1),num('wheel','Rolling circumference (mm)',2100,500,3000),num('cadence','Cadence (rpm)',80,1,250)],v=>{const ratio=+v.front/+v.rear,development=ratio*+v.wheel/1000,speed=development*+v.cadence*60/1000;show({label:'Estimated speed',value:n(speed)+' km/h',details:[['Gear ratio',n(ratio)],['Distance per crank turn',n(development)+' m'],['Cadence',v.cadence+' rpm']],copy:speed.toFixed(2)+' km/h'});},{label:'Calculate gearing'}),
 'swim-pace':()=>form(mount,[num('distance','Swim distance (m)',1000,1,100000),text('time','Elapsed time (HH:MM:SS)','00:25:00'),sel('pool','Pool length (m)',[25,50],25)],v=>{const s=durationSeconds(v.time);need(s>0,'Enter a positive time.');show({label:'Pace per 100 m',value:formatDuration(s/+v.distance*100).replace(/^00:/,''),details:[['Time per pool length',n(s/+v.distance*+v.pool)+' sec'],['Pool lengths',n(+v.distance/+v.pool)],['Average speed',n(+v.distance/s)+' m/s']],copy:formatDuration(s/+v.distance*100)+' / 100 m'});},{label:'Calculate swim pace'}),
 edpi:()=>form(mount,[num('dpi','Mouse DPI',800,1,64000),num('sensitivity','In-game sensitivity',.5,.001,100)],v=>show({label:'Effective DPI',value:n(+v.dpi*+v.sensitivity),details:[['Formula','DPI × sensitivity']],copy:String(+v.dpi*+v.sensitivity),note:'Compare this value only within the same game or sensitivity scale.'}),{label:'Calculate eDPI'}),
 'sensitivity-converter':()=>form(mount,[num('sensitivity','Current sensitivity',2,.001,100),sel('fromProfile','Source profile',[['source','Source / Quake default yaw'],['custom','Custom yaw']],'source'),num('fromYaw','Custom source yaw (degrees per count)',.022,.00001,10),sel('toProfile','Target profile',[['source','Source / Quake default yaw'],['custom','Custom yaw']],'custom'),num('toYaw','Custom target yaw (degrees per count)',.07,.00001,10),num('dpi','Mouse DPI',800,1,64000)],v=>{const a=v.fromProfile==='source'?.022:+v.fromYaw,b=v.toProfile==='source'?.022:+v.toYaw,r=+v.sensitivity*a/b;show({label:'Equivalent target sensitivity',value:n(r),details:[['Source / target yaw',a+' / '+b],['Idealized cm per 360° turn',n(360/(+v.dpi*+v.sensitivity*a)*2.54)+' cm']],copy:String(r),note:'Yaw values are visible assumptions. Matching ideal turn distance does not account for FOV, acceleration or different aiming modes.'});},{label:'Convert sensitivity'})
 };need(forms[id],'This sport tool is unavailable.');forms[id]();}
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=secureIndex(i+1);[a[i],a[j]]=[a[j],a[i]];}return a;};
function bracket(mount,out){let seeds=[],winners=[];form(mount,[area('players','One player or team per line','Aarya\nNabi\nMaya\nArjun\nTara\nKabir'),sel('order','Seeding',[['keep','Keep entered order'],['random','Shuffle randomly']],'keep')],v=>{seeds=v.players.split(/\n/).map(x=>x.trim()).filter(Boolean);need(seeds.length>=2&&seeds.length<=32&&new Set(seeds).size===seeds.length,'Enter 2–32 unique participant names.');if(v.order==='random')seeds=shuffle(seeds);const size=2**Math.ceil(Math.log2(seeds.length));const entered=seeds;seeds=Array.from({length:size/2},(_,i)=>[entered[i]||null,entered[i+size/2]||null]).flat();winners=Array.from({length:Math.log2(size)},()=>[]);render();},{label:'Generate bracket'});function render(){let teams=seeds,html='',rows=[];for(let r=0;r<winners.length;r++){html+=`<section class="bracket-round"><h3>Round ${r+1}</h3>`;const next=[];for(let i=0;i<teams.length;i+=2){const a=teams[i],b=teams[i+1],m=i/2;if(r===0&&(!a||!b))winners[r][m]=a||b;if(winners[r][m]&&!([a,b].includes(winners[r][m])))winners[r][m]=null;const selected=winners[r][m]||'';html+=`<label class="field"><span>${e(a||'TBD / bye')} vs ${e(b||'TBD / bye')}</span><select data-round="${r}" data-match="${m}" ${!a||!b?'disabled':''}><option value="">Choose winner</option>${[a,b].filter(Boolean).map(x=>`<option ${selected===x?'selected':''}>${e(x)}</option>`).join('')}</select></label>`;next.push(selected||null);rows.push({round:r+1,match:m+1,first:a||'',second:b||'',winner:selected});}html+='</section>';teams=next;}result(out,{label:'Champion',value:teams[0]||'To be decided',html:'<div class="bracket-grid">'+html+'</div>',copy:JSON.stringify(rows,null,2)});out.querySelectorAll('[data-round]').forEach(s=>s.onchange=()=>{const r=+s.dataset.round;winners[r][+s.dataset.match]=s.value;for(let j=r+1;j<winners.length;j++)winners[j]=[];render();});exportCSV(out,rows,'nepocore-bracket.csv');}}
function chess(mount,out){let remaining=[300,300],active=null,resumePlayer=0,increment=2,last=0,timer;mount.innerHTML='<h2>Your next move</h2><form><div class="form-grid">'+[num('minutes','Minutes per player',5,.1,180),num('increment','Increment per move (seconds)',2,0,60,1)].map(field).join('')+'</div><button class="btn secondary small" type="submit">Set / reset clocks</button></form><div class="chess-clocks"><button data-player="0" class="chess-clock">05:00</button><button data-player="1" class="chess-clock">05:00</button></div><div class="form-actions"><button class="btn primary" data-start>Start player 1</button><button class="btn secondary" data-pause>Pause</button></div>';const clocks=[...mount.querySelectorAll('[data-player]')],start=mount.querySelector('[data-start]');function update(){if(active!==null){const now=performance.now();remaining[active]-=(now-last)/1000;last=now;if(remaining[active]<=0){remaining[active]=0;const loser=active;active=null;start.disabled=true;outputText(out,'Player '+(loser+1)+' time expired.');}}clocks.forEach((b,i)=>{b.textContent=timerDisplay(remaining[i]);b.classList.toggle('clock-active',active===i);b.setAttribute('aria-label','Player '+(i+1)+' clock '+timerDisplay(remaining[i]));});}function reset(){active=null;resumePlayer=0;remaining=[+mount.querySelector('[name=minutes]').value*60,+mount.querySelector('[name=minutes]').value*60];increment=+mount.querySelector('[name=increment]').value;start.disabled=false;start.textContent='Start player 1';update();outputText(out,'Start player 1, then tap the active player’s clock after each move.');}mount.querySelector('form').onsubmit=ev=>{ev.preventDefault();if(ev.currentTarget.reportValidity())reset();};clocks.forEach((b,i)=>b.onclick=()=>{if(active!==i)return;update();if(active===null)return;remaining[i]+=increment;active=1-i;resumePlayer=active;last=performance.now();update();});start.onclick=()=>{if(active!==null||remaining[resumePlayer]<=0)return;active=resumePlayer;last=performance.now();update();};mount.querySelector('[data-pause]').onclick=()=>{update();if(active!==null){resumePlayer=active;active=null;start.textContent='Resume player '+(resumePlayer+1);}update();};timer=setInterval(update,100);reset();return()=>clearInterval(timer);}
function intervals(mount,out){let timer,running=false,elapsed=0,started=0,segments=[];mount.innerHTML='<h2>Make room for movement</h2><form><div class="form-grid">'+[num('work','Work (seconds)',30,1,3600,1),num('rest','Rest (seconds)',15,0,3600,1),num('rounds','Rounds',8,1,100,1)].map(field).join('')+'</div><button class="btn secondary small" type="submit">Set / reset timer</button></form><div class="interval-stage"><span data-phase>Ready</span><strong data-time>00:30</strong><small data-round>8 rounds</small></div><div class="form-actions"><button class="btn primary" data-start>Start / resume</button><button class="btn secondary" data-pause>Pause</button></div>';const display=mount.querySelector('[data-time]'),phase=mount.querySelector('[data-phase]'),round=mount.querySelector('[data-round]');function tick(){let remaining=elapsed+(running?(performance.now()-started)/1000:0),current;for(const seg of segments){if(remaining<seg.seconds){current=seg;break;}remaining-=seg.seconds;}if(!current){elapsed=segments.reduce((sum,s)=>sum+s.seconds,0);running=false;phase.textContent='Complete';display.textContent='00:00';round.textContent='Session finished';return;}phase.textContent=current.label;display.textContent=timerDisplay(Math.ceil(current.seconds-remaining));round.textContent='Round '+current.round+' of '+mount.querySelector('[name=rounds]').value;}function reset(){running=false;elapsed=0;const f=mount.querySelector('form');segments=[];for(let i=1;i<=+f.elements.rounds.value;i++){segments.push({label:'Work',seconds:+f.elements.work.value,round:i});if(i<+f.elements.rounds.value&&+f.elements.rest.value)segments.push({label:'Rest',seconds:+f.elements.rest.value,round:i});}tick();outputText(out,'Alternating work and rest. The last work interval ends the session.');}mount.querySelector('form').onsubmit=ev=>{ev.preventDefault();if(ev.currentTarget.reportValidity())reset();};mount.querySelector('[data-start]').onclick=()=>{if(running)return;if(elapsed>=segments.reduce((sum,s)=>sum+s.seconds,0))elapsed=0;started=performance.now();running=true;tick();};mount.querySelector('[data-pause]').onclick=()=>{if(!running)return;elapsed+=(performance.now()-started)/1000;running=false;tick();};timer=setInterval(tick,100);reset();return()=>clearInterval(timer);}
function reaction(mount,out){let phase='idle',readyAt=0,timer,results=[];mount.innerHTML='<h2>Ready when you are</h2><button class="reaction-panel" data-reaction>Tap to begin</button><p class="form-note">Wait for green, then tap. Early taps do not count.</p><button class="btn secondary" data-reset>Reset attempts</button>';const panel=mount.querySelector('[data-reaction]');function render(){result(out,{label:'Completed attempts',value:results.length,details:results.length?[['Latest',n(results.at(-1))+' ms'],['Average',n(results.reduce((a,b)=>a+b,0)/results.length)+' ms'],['Best',n(Math.min(...results))+' ms']]:[],copy:results.join(', '),note:'Device and display latency affect these casual measurements.'});}panel.onclick=()=>{if(phase==='waiting'){clearTimeout(timer);phase='idle';panel.className='reaction-panel';panel.textContent='Too soon! Tap to try again.';return;}if(phase==='ready'){results.push(Math.round(performance.now()-readyAt));phase='idle';panel.className='reaction-panel';panel.textContent=results.at(-1)+' ms — tap again';render();return;}phase='waiting';panel.className='reaction-panel waiting';panel.textContent='Wait for green…';timer=setTimeout(()=>{phase='ready';panel.className='reaction-panel ready';panel.textContent='Tap now!';readyAt=performance.now();},1200+secureIndex(2400));};mount.querySelector('[data-reset]').onclick=()=>{clearTimeout(timer);phase='idle';results=[];panel.className='reaction-panel';panel.textContent='Tap to begin';render();};render();return()=>clearTimeout(timer);}
function aim(mount,out){let running=false,hits=0,clicks=0,end=0,timer;mount.innerHTML='<h2>A little target practice</h2><div class="form-grid">'+[num('duration','Round length (seconds)',20,5,120,1),num('size','Target size (px)',50,32,90,1)].map(field).join('')+'</div><button class="btn primary" data-start>Start round</button><p data-score class="form-note">Hit the targets before time runs out.</p><div class="aim-stage"><button class="aim-target" aria-label="Target" hidden></button></div>';const target=mount.querySelector('.aim-target'),stage=mount.querySelector('.aim-stage'),score=mount.querySelector('[data-score]'),start=mount.querySelector('[data-start]');function move(){target.style.left=(10+secureIndex(81))+'%';target.style.top=(15+secureIndex(71))+'%';}function finish(){running=false;clearInterval(timer);target.hidden=true;start.disabled=false;result(out,{label:'Targets hit',value:hits,details:[['Clicks / taps',clicks],['Accuracy',clicks?n(hits/clicks*100)+'%':'—']],copy:`${hits} hits; ${clicks} clicks`});}start.onclick=()=>{if(!mount.querySelector('[name=duration]').reportValidity()||!mount.querySelector('[name=size]').reportValidity())return;running=true;hits=clicks=0;target.style.width=target.style.height=mount.querySelector('[name=size]').value+'px';end=performance.now()+ +mount.querySelector('[name=duration]').value*1000;target.hidden=false;start.disabled=true;move();timer=setInterval(()=>{const left=Math.max(0,(end-performance.now())/1000);score.textContent=left.toFixed(1)+' s · '+hits+' hits · '+clicks+' taps';if(left<=0)finish();},100);};target.onclick=ev=>{ev.stopPropagation();if(!running)return;hits++;clicks++;move();};stage.onclick=()=>{if(running)clicks++;};return()=>clearInterval(timer);}
function memory(mount,out){let cards=[],open=[],matched=new Set(),moves=0,started=0,lock=false,timeout,timer;const symbols=['✦','☀','☂','☘','♜','♫','♥','★','⚑','☾','❀','♢'];mount.innerHTML='<h2>Find the little pairs</h2><label class="field"><span>Board size</span><select data-size><option value="8">8 cards</option><option value="16" selected>16 cards</option><option value="24">24 cards</option></select></label><button class="btn secondary small" data-new>New game</button><p class="form-note" data-stats></p><div class="memory-board"></div>';const board=mount.querySelector('.memory-board'),stats=mount.querySelector('[data-stats]');function update(){stats.textContent=moves+' moves · '+matched.size/2+' / '+cards.length/2+' pairs · '+timerDisplay((performance.now()-started)/1000);}function render(){board.replaceChildren();cards.forEach((value,i)=>{const b=document.createElement('button');const shown=open.includes(i)||matched.has(i);b.className='memory-card'+(shown?' revealed':'');b.textContent=shown?value:'?';b.disabled=matched.has(i);b.setAttribute('aria-label','Card '+(i+1)+(shown?': '+value:', hidden'));b.onclick=()=>{if(lock||open.includes(i)||matched.has(i))return;open.push(i);render();if(open.length===2){moves++;if(cards[open[0]]===cards[open[1]]){open.forEach(i=>matched.add(i));open=[];render();if(matched.size===cards.length){clearInterval(timer);result(out,{label:'All pairs found',value:moves+' moves',details:[['Elapsed',timerDisplay((performance.now()-started)/1000)]],copy:moves+' moves'});}}else{lock=true;timeout=setTimeout(()=>{open=[];lock=false;render();},650);}update();}};board.append(b);});}function reset(){clearTimeout(timeout);clearInterval(timer);const count=+mount.querySelector('[data-size]').value;cards=shuffle([...symbols.slice(0,count/2),...symbols.slice(0,count/2)]);open=[];matched=new Set();moves=0;lock=false;started=performance.now();render();update();timer=setInterval(update,1000);outputText(out,'Reveal two cards at a time to find matching symbols.');}mount.querySelector('[data-new]').onclick=reset;mount.querySelector('[data-size]').onchange=reset;reset();return()=>{clearTimeout(timeout);clearInterval(timer);};}
